      "keystrokes": "cat > /workspace/data/birthdays.md << 'EOF'
# Geburtstage

- **Valentina** - 14.02.2000 (wird 26)
- **Max** - 15.03.1990 (wird 36)
- **Lina** - 29.02.2004 (wird 22)
- **Tom** - 01.12.
EOF
",
      "duration": 0.1
    },
    {
      "keystrokes": "cat /workspace/data/birthdays.json
",
      "duration": 0.1
    },
    {
      "keystrokes": "cat /workspace/data/birthdays.md
",
      "duration": 0.1
    }
